<?php
require_once __DIR__.'/includes/email.php';email_require('view');if(!Auth::isAdmin()&&!Auth::can('email_hub.reports','view')){http_response_code(403);exit('دسترسی غیرمجاز است.');}$pageTitle='گزارش ایمیل سازمانی';$accounts=EmailHubModule::accessibleAccounts('read');$ids=array_map('intval',array_column($accounts,'id'));if(!$ids)$ids=[-1];$ph=implode(',',array_fill(0,count($ids),'?'));$metrics=Database::fetch("SELECT SUM(DATE(date_received)=CURDATE() AND folder_id IN (SELECT id FROM email_folders WHERE folder_type='inbox')) received_today,SUM(DATE(date_sent)=CURDATE() AND folder_id IN (SELECT id FROM email_folders WHERE folder_type='sent')) sent_today,SUM(is_read=0 AND status<>'deleted') unread,SUM(status='pending_reply') pending,SUM(status='replied') replied FROM email_messages WHERE account_id IN ({$ph})",$ids)??[];$avg=Database::fetch("SELECT AVG(TIMESTAMPDIFF(MINUTE,m.date_received,o.sent_at)) avg_minutes FROM email_outbox o JOIN email_messages m ON m.id=o.related_message_id WHERE o.status='sent' AND o.account_id IN ({$ph})",$ids);$byAccount=Database::fetchAll("SELECT a.account_title,COUNT(m.id) message_count,SUM(m.is_read=0 AND m.status<>'deleted') unread_count,a.sync_status FROM email_accounts a LEFT JOIN email_messages m ON m.account_id=a.id WHERE a.id IN ({$ph}) GROUP BY a.id,a.account_title,a.sync_status ORDER BY message_count DESC",$ids);$byUnit=Database::fetchAll("SELECT COALESCE(ou.title,'بدون واحد') unit_title,COUNT(m.id) message_count FROM email_messages m JOIN email_accounts a ON a.id=m.account_id LEFT JOIN org_units ou ON ou.id=a.department_id WHERE m.account_id IN ({$ph}) GROUP BY ou.id,ou.title ORDER BY message_count DESC",$ids);$errors=Database::fetchAll("SELECT l.*,a.account_title FROM email_logs l LEFT JOIN email_accounts a ON a.id=l.account_id WHERE l.account_id IN ({$ph}) AND l.action IN ('sync_failed','send_failed') ORDER BY l.id DESC LIMIT 50",$ids);require __DIR__.'/../views/partials/admin-header.php';?>
<div class="email-page-head"><div><h1>گزارش ایمیل سازمانی</h1><p>وضعیت مکاتبات، پاسخ‌گویی و سلامت اتصال حساب‌ها</p></div></div><?php email_tabs('reports')?><section class="email-kpis report"><article><span>دریافتی امروز</span><strong><?=e((string)($metrics['received_today']??0))?></strong></article><article><span>ارسالی امروز</span><strong><?=e((string)($metrics['sent_today']??0))?></strong></article><article><span>خوانده‌نشده</span><strong><?=e((string)($metrics['unread']??0))?></strong></article><article><span>نیازمند پاسخ</span><strong><?=e((string)($metrics['pending']??0))?></strong></article><article><span>پاسخ‌داده‌شده</span><strong><?=e((string)($metrics['replied']??0))?></strong></article><article><span>میانگین پاسخ</span><strong><?=e($avg&&$avg['avg_minutes']!==null?round((float)$avg['avg_minutes']).' دقیقه':'—')?></strong></article></section><div class="email-report-grid"><section class="card"><h2>وضعیت حساب‌ها</h2><div class="table-wrap"><table><thead><tr><th>حساب</th><th>کل ایمیل</th><th>خوانده‌نشده</th><th>اتصال</th></tr></thead><tbody><?php foreach($byAccount as $r):?><tr><td><?=e($r['account_title'])?></td><td><?=e((string)$r['message_count'])?></td><td><?=e((string)$r['unread_count'])?></td><td><span class="email-status status-<?=e($r['sync_status'])?>"><?=e(['never'=>'بدون Sync','syncing'=>'در حال Sync','ok'=>'سالم','error'=>'دارای خطا'][$r['sync_status']]??'')?></span></td></tr><?php endforeach?></tbody></table></div></section><section class="card"><h2>تعداد ایمیل هر واحد</h2><div class="email-unit-bars"><?php $max=max(array_map('intval',array_column($byUnit,'message_count'))?:[1]);foreach($byUnit as $r):?><div><span><?=e($r['unit_title'])?></span><b style="--value:<?=e((string)round(100*(int)$r['message_count']/max(1,$max)))?>%"></b><strong><?=e((string)$r['message_count'])?></strong></div><?php endforeach?></div></section></div><section class="card"><h2>خطاهای Sync و ارسال</h2><div class="table-wrap"><table><thead><tr><th>زمان</th><th>حساب</th><th>عملیات</th><th>پیام کاربری</th></tr></thead><tbody><?php foreach($errors as $eRow):?><tr><td><?=e(format_jalali_datetime($eRow['created_at']))?></td><td><?=e($eRow['account_title']?:'—')?></td><td><?=e($eRow['action']==='sync_failed'?'همگام‌سازی':'ارسال')?></td><td><?=e($eRow['description']?:'خطای ثبت‌شده')?></td></tr><?php endforeach?><?php if(!$errors):?><tr><td colspan="4">خطای اخیر ثبت نشده است.</td></tr><?php endif?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
